    wire [9:0] state_bin;
    wire [9:0] state_onehot;
    wire [9:0] state_next;
    wire [9:0] state_next_bin;
    wire [9:0] state_next_onehot;
    wire out1, out2;

    // Combinational state to one-hot conversion.
    assign state_onehot = 10'b0000000001 << state[9:0];

    // Combinational one-hot to binary state transition.
    always @* begin
        state_bin = 10'b0000000000;
        for (int i=0; i<10; i=i+1) begin
            if (state_onehot[i]) begin
                state_bin[i] = 1'b1;
            end
        end
        state_next_bin = state_bin;
        case (state_bin)
            10'b0000000001: state_next_bin = 10'b0000000010;
            10'b0000000010: state_next_bin = 10'b0000000100;
            10'b0000000100: state_next_bin = 10'b0000001000;
            10'b0000001000: state_next_bin = 10'b0000010000;
            10'b0000010000: state_next_bin = 10'b0000100000;
