            10'b0001000000: state_next_bin = (in ? 10'b0010000000 : 10'b0000000001);
            10'b0010000000: state_next_bin = 10'b0100000000;
            10'b0100000000: state_next_bin = 10'b1000000000;
            default: state_next_bin = 10'b0000000001;
        endcase
