    // Combinational one-hot to one-hot state transition.
    always @* begin
        state_next_onehot = 10'b0000000000;
        for (int i=0; i<10; i=i+1) begin
            if (state_next_bin[i]) begin
                state_next_onehot[i] = 1'b1;
            end
